#[derive(Debug)]
enum Direction {
    North,
    East,
    South,
    West,
}

fn main() {
    let heading = Direction::East;
    println!("Heading: {:?}", heading);

    let all = [Direction::North, Direction::East, Direction::South, Direction::West];
    for d in all {
        println!("{:?}", d);
    }
}

enum Shape {
    Circle(f64),
    Rectangle { width: f64, height: f64 },
    Dot,
}

fn main() {
    let shapes = [
        Shape::Circle(1.5),
        Shape::Rectangle { width: 2.0, height: 3.0 },
        Shape::Dot,
    ];
    for s in shapes {
        match s {
            Shape::Circle(radius) => println!("circle, radius {radius}"),
            Shape::Rectangle { width, height } => println!("rectangle, {width} by {height}"),
            Shape::Dot => println!("a dot"),
        }
    }
}

#[derive(Debug)]
enum Light {
    Red,
    Yellow,
    Green,
}

impl Light {
    fn seconds(&self) -> u32 {
        match self {
            Light::Red => 30,
            Light::Yellow => 3,
            Light::Green => 25,
        }
    }
}

fn main() {
    for light in [Light::Red, Light::Yellow, Light::Green] {
        println!("{:?} lasts {} seconds", light, light.seconds());
    }
}

